referenceSolutions.javascript:
export function solve(items) {
  if (!items.length) return { status: "pending", value: null, time: null };
  const first = items
    .map((x, i) => ({ ...x, i }))
    .sort((a, b) => a.delay - b.delay || a.i - b.i)[0];
  return { status: first.status, value: first.value, time: first.delay };
}

